import json,sys,re
keys={'wang2025computational','anon2025decision','kulkarni2025machine','gullbrekken2025phase','hong2024combined','k2026influence','janani2014influence','aman2026susceptor','heo2021microstructural','klimpel2023standardizing','zhang2026femtosecond','zhang2023bilayer'}
for n,line in enumerate(open(sys.argv[1],encoding='utf8'),1):
 try:d=json.loads(line)
 except: continue
 vals={str(d.get(k,'')) for k in ('citekey','key','bibkey','ref_key')}
 if keys & vals:
  k=(keys&vals).pop(); print('\\n###',k); print('title:',d.get('title')); print('year:',d.get('year'),'doi:',d.get('doi')); a=d.get('abstract') or ''; print('abstract:',re.sub(r'\\s+',' ',a)[:1800])
PY"

